{"command": "cd /tmp/t4 && python3 - <<'EOF'
import subprocess, time, os, pty, select, sys
def run(args):
    m,s=pty.openpty()
    import struct,fcntl,termios
    fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack('HHHH', 24, 100, 0,0))
    os.set_blocking(m, False)
    if os.path.exists('/dev/shm/oX'): os.remove('/dev/shm/oX')
    t=time.perf_counter()
    p=subprocess.Popen(args, stdin=s, stdout=s, stderr=s, close_fds=True)
    n=0
    while time.perf_counter()-t < 30 and p.poll() is None:
        r,_,_=select.select([m],[],[],0.05)
        if r:
            try: d=os.read(m,1<<20)
            except OSError: break
            n+=len(d)
    dt=time.perf_counter()-t
    p.kill()
    return dt, n, os.path.getsize('/dev/shm/oX')
for drv in ['parfile','parblock']:
    for bs in ['1','1000','1000000']:
        dt,n,size=run(['/workspace/executable','--driver',drv,'--reflink','never','--no-perms','--no-timestamps','--block-size',bs,'-w','4','/dev/shm/big2','/dev/shm/oX'])
        print(drv,bs,'time %.3f'%dt,'bytes_out',n,'size',size)
EOF"}

