{"command": "cd /workspace && cat > libfs/src/lib.rs <<'EOF'
//! Filesystem helpers used by `xcp`.
//!
//! These routines deal with the low level filesystem operations required to
//! reproduce a file: extended attributes, permissions, timestamps and the
//! various kinds of special nodes.

pub mod common;
pub mod errors;

pub use common::*;
pub use errors::*;
EOF
cat > libfs/src/errors.rs <<'EOF'
//! Error type shared by the filesystem helpers.

use std::fmt;

/// An error that carries a formatted description plus an optional cause.
#[derive(Debug)]
pub struct FsError {
    message: String,
    cause: Option<Box<dyn std::error::Error + Send + Sync>>,
}

impl FsError {
    /// Build a new error from a message.
    pub fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            cause: None,
        }
    }

    /// Build a new error from a message and an underlying cause.
    pub fn with_cause(
        message: impl Into<String>,
        cause: Box<dyn std::error::Error + Send + Sync>,
    ) -> Self {
        Self {
            message: message.into(),
            cause: Some(cause),
        }
    }
}

impl fmt::Display for FsError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.message)
    }
}

impl std::error::Error for FsError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        self.cause.as_ref().map(|c| &**c as &(dyn std::error::Error + 'static))
    }
}

impl From<std::io::Error> for FsError {
    fn from(e: std::io::Error) -> Self {
        Self::new(e.to_string())
    }
}
EOF
echo ok"}

