import os, pty, sys, select, time, subprocess, termios, struct, fcntl, re
def run(bs, src, dst, wait=3.0):
    m,s=pty.openpty()
    fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack('HHHH', 24, 100, 0,0))
    os.set_blocking(m, False)
    if os.path.exists(dst): os.remove(dst)
    p=subprocess.Popen(['/workspace/executable','--reflink','never','--block-size',bs,'-w','1','--no-perms','--no-timestamps',src,dst], stdin=s, stdout=s, stderr=s, close_fds=True)
