    pub size: u64,
    /// Unix mode bits (including the file type).
    pub mode: u32,
    /// Owner user id.
    pub uid: u32,
    /// Owner group id.
    pub gid: u32,
    /// Number of hard links.
    pub nlink: u64,
    /// Device id.
    pub dev: u64,
    /// Inode number.
    pub ino: u64,
    /// Last access time.
    pub atime: TimeVal,
    /// Last modification time.
    pub mtime: TimeVal,
}

/// Copy the extended attributes from one file to another.
pub fn copy_xattrs(from: &File, to: &File) -> Result<()> {
    log::debug!("Starting xattr copy...");

    let names = list_xattrs(from)?;
    for name in names {
        log::debug!("Copy xattr {:?}", name);
        let value = get_xattr(from, &name)?;
        set_xattr(to, &name, &value)?;
    }
    Ok(())
}

fn list_xattrs(f: &File) -> Result<Vec<String>> {
    let mut size = 256usize;
    loop {
        let mut buf = vec![0u8; size];
        let fd = f.as_raw_fd();
        let n = unsafe { libc::flistxattr(fd, buf.as_mut_ptr() as *mut libc::c_char, buf.len()) };
        if n < 0 {
            let err = std::io::Error::last_os_error();
            if err.raw_os_error() == Some(libc::ERANGE) {
                size *= 2;
                continue;
            }
            return Err(FsError::from(err));
        }
        let n = n as usize;
        buf.truncate(n);
        let mut out = Vec::new();
        for item in buf.split(|c| *c == 0) {
            if item.is_empty() {
                continue;
            }
            match String::from_utf8(item.to_vec()) {
                Ok(s) => out.push(s),
                Err(_) => continue,
            }
        }
        return Ok(out);
    }
}

fn get_xattr(f: &File, name: &str) -> Result<Vec<u8>> {
    let mut size = 256usize;
    loop {
        let mut buf = vec![0u8; size];
        let fd = f.as_raw_fd();
        let n = unsafe {
            libc::fgetxattr(
                fd,
                name.as_ptr() as *const libc::c_char,
                buf.as_mut_ptr() as *mut libc::c_void,
                buf.len(),
            )
        };
        if n < 0 {
            let err = std::io::Error::last_os_error();
            if err.raw_os_error() == Some(libc::ERANGE) {
                size *= 2;
                continue;
            }
            return Err(FsError::from(err));
        }
        let n = n as usize;
        buf.truncate(n);
        return Ok(buf);
    }
}

fn set_xattr(f: &File, name: &str, value: &[u8]) -> Result<()> {
    let fd = f.as_raw_fd();
    let res = unsafe {
        libc::fsetxattr(
            fd,
            name.as_ptr() as *const libc::c_char,
            value.as_ptr() as *const libc::c_void,
            value.len(),
            0,
        )
    };
    if res < 0 {
        return Err(FsError::from(std::io::Error::last_os_error()));
    }
    Ok(())
}

/// Copy the permission bits from `info` onto the destination file.
pub fn copy_permissions(info: &SourceInfo, to: &File) -> Result<()> {
    log::debug!("Performing permissions copy");
    let mode = (info.mode & 0o7777) as libc::mode_t;
    let res = unsafe { libc::fchmod(to.as_raw_fd(), mode) };
    if res < 0 {
        return Err(FsError::from(std::io::Error::last_os_error()));
    }
    Ok(())
}

/// Copy the access and modification times from `info`.
pub fn copy_timestamps(info: &SourceInfo, to: &File) -> Result<()> {
    log::debug!("Performing timestamp copy");
    let times = [
        libc::timespec {
            tv_sec: info.atime.sec as libc::time_t,
            tv_nsec: info.atime.nsec as libc::c_long,
        },
        libc::timespec {
            tv_sec: info.mtime.sec as libc::time_t,
            tv_nsec: info.mtime.nsec as libc::c_long,
        },
    ];
    let res = unsafe { libc::futimens(to.as_raw_fd(), times.as_ptr()) };
    if res < 0 {
        return Err(FsError::from(std::io::Error::last_os_error()));
    }
    Ok(())
}

/// Copy ownership (user/group) onto the destination file.
pub fn copy_ownership(info: &SourceInfo, to: &File) -> Result<()> {
    let res = unsafe { libc::fchown(to.as_raw_fd(), info.uid, info.gid) };
    if res < 0 {
        return Err(FsError::from(std::io::Error::last_os_error()));
    }
    Ok(())
}

/// Fetch the stat information of an open file.
pub fn fstat(f: &File) -> Result<SourceInfo> {
    let mut st: libc::stat = unsafe { std::mem::zeroed() };
    let res = unsafe { libc::fstat(f.as_raw_fd(), &mut st) };
    if res < 0 {
        return Err(FsError::from(std::io::Error::last_os_error()));
    }
    Ok(stat_to_info(&st))
}

fn stat_to_info(st: &libc::stat) -> SourceInfo {
    SourceInfo {
        size: st.st_size as u64,
        mode: st.st_mode as u32,
        uid: st.st_uid,
        gid: st.st_gid,
        nlink: st.st_nlink as u64,
        dev: st.st_dev as u64,
        ino: st.st_ino as u64,
        atime: TimeVal {
            sec: st.st_atime as i64,
            nsec: st.st_atime_nsec as i64,
        },
        mtime: TimeVal {
            sec: st.st_mtime as i64,
            nsec: st.st_mtime_nsec as i64,
        },
    }
}

/// Stat a path following symlinks.
pub fn stat_path(p: &Path) -> Result<SourceInfo> {
    let mut st: libc::stat = unsafe { std::mem::zeroed() };
    let c = cstr(p)?;
    let res = unsafe { libc::stat(c.as_ptr(), &mut st) };
    if res < 0 {
        return Err(FsError::from(std::io::Error::last_os_error()));
    }
    Ok(stat_to_info(&st))
}

/// Stat a path without following symlinks.
pub fn lstat_path(p: &Path) -> Result<SourceInfo> {
    let mut st: libc::stat = unsafe { std::mem::zeroed() };
    let c = cstr(p)?;
    let res = unsafe { libc::lstat(c.as_ptr(), &mut st) };
    if res < 0 {
        return Err(FsError::from(std::io::Error::last_os_error()));
    }
    Ok(stat_to_info(&st))
}

fn cstr(p: &Path) -> Result<std::ffi::CString> {
    use std::os::unix::ffi::OsStrExt;
    std::ffi::CString::new(p.as_os_str().as_bytes())
        .map_err(|_| FsError::new("path contains interior NUL byte"))
}

/// Create a special file (fifo/socket/device) at `to`.
pub fn make_special(info: &SourceInfo, to: &Path) -> Result<()> {
    let c = cstr(to)?;
    let res = unsafe { libc::mknod(c.as_ptr(), info.mode as libc::mode_t, info.dev as libc::dev_t) };
    if res < 0 {
        return Err(FsError::from(std::io::Error::last_os_error()));
    }
    Ok(())
}

/// Create a symbolic link.
pub fn make_symlink(target: &Path, to: &Path) -> Result<()> {
    let t = cstr(target)?;
    let c = cstr(to)?;
    let res = unsafe { libc::symlink(t.as_ptr(), c.as_ptr()) };
    if res < 0 {
        return Err(FsError::from(std::io::Error::last_os_error()));
    }
    Ok(())
}

/// Read the target of a symbolic link.
pub fn read_link(p: &Path) -> Result<std::path::PathBuf> {
    std::fs::read_link(p).map_err(FsError::from)
}

/// Create a directory.
pub fn create_dir(p: &Path) -> Result<()> {
    std::fs::create_dir(p).map_err(FsError::from)
}
EOF
echo ok"}

