//! Error types used throughout xcp.

use std::fmt;
use std::path::PathBuf;

use walkdir::Error as WalkError;

/// The single error type used by the copy machinery.
///
/// It renders as `<kind>: <message>` and, where a cause is available, the
/// standard `Caused by:` block is produced by the Debug implementation.
#[derive(Debug)]
pub struct Error {
    kind: &'static str,
    message: String,
    suffix: Option<String>,
    cause: Option<Box<dyn std::error::Error + Send + Sync>>,
}

impl Error {
    /// Create an error with the given kind and message.
    pub fn new(kind: &'static str, message: impl Into<String>) -> Self {
        Self {
            kind,
            message: message.into(),
            suffix: None,
            cause: None,
        }
    }

    /// Create an error which also reports a path.
    pub fn with_path(kind: &'static str, message: impl Into<String>, path: PathBuf) -> Self {
        Self {
            kind,
            message: message.into(),
            suffix: Some(path.to_string_lossy().into_owned()),
            cause: None,
        }
    }

    /// Create an error wrapping an underlying cause.
    pub fn with_cause(
        kind: &'static str,
        message: impl Into<String>,
        cause: Box<dyn std::error::Error + Send + Sync>,
    ) -> Self {
        Self {
            kind,
            message: message.into(),
            suffix: None,
            cause: Some(cause),
        }
    }

    /// Wrap an `std::io::Error` into the copy failure kind.
    pub fn io(e: std::io::Error) -> Self {
        Self::new(COPY, e.to_string())
    }

    /// Attach a cause to this error.
    pub fn caused_by(mut self, cause: Box<dyn std::error::Error + Send + Sync>) -> Self {
        self.cause = Some(cause);
        self
    }
}

/// Kind used for copy failures.
pub const COPY: &str = "Error during copy";
/// Kind used for invalid arguments.
pub const INVALID_ARGS: &str = "Invalid arguments";
/// Kind used for invalid source specifications.
pub const INVALID_SOURCE: &str = "Invalid source";
/// Kind used for invalid destinations.
pub const INVALID_DEST: &str = "Invalid destination";
/// Kind used when a destination exists and --no-clobber was given.
pub const DEST_EXISTS: &str = "Destination Exists";

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}: {}", self.kind, self.message)?;
        if let Some(p) = &self.suffix {
            write!(f, ", {}", p)?;
        }
        Ok(())
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        self.cause
            .as_ref()
            .map(|c| &**c as &(dyn std::error::Error + 'static))
    }
}

/// Wrap a walkdir error so that its cause chain is preserved.
pub fn from_walk(e: WalkError) -> Error {
    let msg = e.to_string();
    let cause = e
        .io_error()
        .map(|io| Box::new(io) as Box<dyn std::error::Error + Send + Sync>);
    Error {
        kind: "",
        message: msg,
        suffix: None,
        cause,
    }
}
EOF
