//! Parsing helpers for the option values.

use crate::errors::*;

/// Parse a human readable byte size such as `1MB` or `1024` into a count of
/// bytes.
///
/// Follows the behaviour of the `unbytify` crate which the original tool uses:
/// the unit is optional, scientific notation is accepted and a missing unit
/// requires the value to be an exact integer.
pub fn parse_block_size(input: &str) -> Result<u64, Error> {
    let s = input.trim();
    if s.is_empty() {
        // The underlying parser slices the string unconditionally which
        // panics for an empty input; reproduce that behaviour.
        let _ = &s[1..];
    }

    // Determine the trailing alphabetic unit suffix.
    let bytes = s.as_bytes();
    let mut unit_start = bytes.len();
    while unit_start > 0 && bytes[unit_start - 1].is_ascii_alphabetic() {
        unit_start -= 1;
    }
    let (num, unit) = s.split_at(unit_start);
    let (has_unit, mult) = unit_multiplier(unit.trim())?;

    let num = num.trim();
    let mut it = num.chars().peekable();
    let mut negative = false;
    if let Some(&c) = it.peek() {
        if c == '+' || c == '-' {
            negative = c == '-';
            it.next();
        }
    }
    let mut int_part: u64 = 0;
    let mut int_digits = 0usize;
    while let Some(&c) = it.peek() {
        if let Some(d) = c.to_digit(10) {
            int_part = int_part
                .saturating_mul(10)
                .saturating_add(d as u64);
            int_digits += 1;
            it.next();
        } else {
            break;
        }
    }
    let mut frac_value: f64 = 0.0;
    let mut has_frac = false;
    if let Some(&c) = it.peek() {
        if c == '.' {
            it.next();
            has_frac = true;
            let mut digits = Vec::new();
            while let Some(&c2) = it.peek() {
                if let Some(d) = c2.to_digit(10) {
                    digits.push(d);
                    it.next();
                } else {
                    break;
                }
            }
            let mut scale = 1.0f64;
            for d in &digits {
                frac_value += *d as f64 * scale;
                scale /= 10.0;
            }
        }
    }
    let mut exp: i32 = 0;
    let mut has_exp = false;
    let mut exp_huge = false;
    if let Some(&c) = it.peek() {
        if c == 'e' || c == 'E' {
            it.next();
            has_exp = true;
            let mut neg = false;
            if let Some(&c2) = it.peek() {
                if c2 == '+' || c2 == '-' {
                    neg = c2 == '-';
                    it.next();
                }
            }
            let mut edigits = String::new();
            while let Some(&c3) = it.peek() {
                if c3.is_ascii_digit() {
                    edigits.push(c3);
                    it.next();
                } else {
                    break;
                }
            }
            if edigits.is_empty() {
                // The original treats a missing exponent as a very large one.
                exp_huge = true;
            } else {
                match edigits.parse::<u32>() {
                    Ok(v) => exp = if neg { -(v as i32) } else { v as i32 },
                    Err(_) => return Err(invalid_size(input)),
                }
            }
        }
    }
    if it.peek().is_some() {
        return Err(invalid_size(input));
    }
    if int_digits == 0 && !has_frac {
        return Err(invalid_size(input));
    }
    if negative {
        return Err(invalid_size(input));
    }

    let sign_mult = if exp_huge {
        // Saturate at a value which is far beyond any real size.
        u64::MAX as f64
    } else {
        10f64.powi(exp)
    };

    let mut value = (int_part as f64 + frac_value) * mult as f64 * sign_mult;
    if int_part == 0 && has_frac && !has_exp && mult > 1 {
        // Matches the (quirky) behaviour of the reference implementation.
        value = 0.0;
    }
    if !has_unit && has_frac && frac_value.fract() != 0.0 {
        // Without a unit the value has to be an exact integer.
        return Err(invalid_size(input));
    }
    if value < 0.0 || value > u64::MAX as f64 {
        return Ok(u64::MAX);
    }
    Ok(value as u64)
}

fn invalid_size(input: &str) -> Error {
    Error::new(
        INVALID_ARGS,
        format!("could not interpret string as byte size for '{}'", input),
    )
}

fn unit_multiplier(unit: &str) -> Result<(bool, u64), Error> {
    let lower: String = unit.to_lowercase();
    match lower.as_str() {
        "" => Ok((false, 1)),
        "b" => Ok((true, 1)),
        "k" | "kb" | "kib" | "ki" => Ok((true, 1024)),
        "m" | "mb" | "mib" | "mi" => Ok((true, 1024u64 * 1024)),
        "g" | "gb" | "gib" | "gi" => Ok((true, 1024u64 * 1024 * 1024)),
        "t" | "tb" | "tib" | "ti" => Ok((true, 1024u64 * 1024 * 1024 * 1024)),
        "p" | "pb" | "pib" | "pi" => Ok((true, 1024u64 * 1024 * 1024 * 1024 * 1024)),
        "e" | "eb" | "eib" | "ei" => Ok((true, 1024u64 * 1024 * 1024 * 1024 * 1024 * 1024)),
        _ => Err(Error::new(
            INVALID_ARGS,
            "could not interpret string as byte size",
        )),
    }
}

/// Driver selection.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Driver {
    /// Parallelise at the file level (the default).
    ParFile,
    /// Parallelise at the block level.
    ParBlock,
}

impl Driver {
    /// Parse a driver name.
    pub fn parse(s: &str) -> Result<Self, Error> {
        let lower = s.to_lowercase();
        match lower.as_str() {
            "parfile" => Ok(Driver::ParFile),
