    pub fn with_path(kind: &'static str, message: impl Into<String>, path: PathBuf) -> Self {
        Self {
            kind,
            message: message.into(),
            suffix: Some(path.to_string_lossy().into_owned()),
            cause: None,
        }
    }

    /// Attach a cause to this error.
    pub fn caused_by(mut self, cause: Box<dyn std::error::Error + Send + Sync>) -> Self {
        self.cause = Some(cause);
        self
    }
}

/// Kind used for copy failures.
pub const COPY: &str = "Error during copy";
/// Kind used for invalid arguments.
