/// Kind used for invalid source specifications.
pub const INVALID_SOURCE: &str = "Invalid source";
/// Kind used for invalid destinations.
pub const INVALID_DEST: &str = "Invalid destination";
/// Kind used when a destination exists and --no-clobber was given.
pub const DEST_EXISTS: &str = "Destination Exists";

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.kind.is_empty() {
            write!(f, "{}", self.message)?;
        } else {
            write!(f, "{}: {}", self.kind, self.message)?;
        }
        if let Some(p) = &self.suffix {
            write!(f, ", {}", p)?;
        }
        Ok(())
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        self.cause
            .as_ref()
            .map(|c| &**c as &(dyn std::error::Error + 'static))
    }
}

impl fmt::Debug for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(self, f)?;
        let mut chain = Vec::new();
        let mut cur: Option<&(dyn std::error::Error + 'static)> = self.source();
        while let Some(c) = cur {
