//! Progress bar ("feedback") implementation.
//!
//! A background thread owns the display state.  Copy workers report progress
//! through a channel; the thread renders the bar on its own cadence.

use std::io::Write;
use std::sync::mpsc::{channel, RecvTimeoutError, Sender};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use crate::errors::*;
use libfs::common as fsops;

/// Interval between automatic redraws.
const REFRESH: Duration = Duration::from_millis(50);
/// Short interval used while the transfer is just starting up.
const EARLY: Duration = Duration::from_millis(1);
/// Number of updates which are always drawn immediately.
const BURST: usize = 10;

/// Message sent to the feedback thread.
pub enum Event {
    /// Increase the total byte count by `n`.
    AddTotal(u64),
    /// Report `n` more bytes as having been transferred.
    Add(u64),
    /// The transfer has finished; force a final redraw.
    Finish,
}

/// Handle used by the workers to report progress.
#[derive(Clone)]
pub struct Reporter {
    tx: Option<Sender<Event>>,
}

impl Reporter {
    /// Report that `n` more bytes have been transferred.
    pub fn add(&self, n: u64) -> Result<(), Error> {
        if let Some(tx) = &self.tx {
            tx.send(Event::Add(n)).map_err(|_| {
                Error::new(COPY, "Error during copy operation")
            })?;
        }
        Ok(())
    }

    /// Report that `n` more bytes belong to the total.
    pub fn add_total(&self, n: u64) {
        if let Some(tx) = &self.tx {
            let _ = tx.send(Event::AddTotal(n));
        }
    }

    /// Signal completion.
    pub fn finish(&self) {
        if let Some(tx) = &self.tx {
            let _ = tx.send(Event::Finish);
        }
    }
}

/// Owns the feedback thread.
pub struct Feedback {
    reporter: Reporter,
    handle: Option<JoinHandle<()>>,
}

impl Feedback {
    /// Start the feedback thread.  `enabled` controls whether anything is
    /// actually drawn.
    pub fn new(enabled: bool) -> Self {
        let (tx, rx) = channel::<Event>();
        let handle = std::thread::spawn(move || {
            let mut state = State::new();
            let start = Instant::now();
            let mut draws = 0usize;
            let mut last_draw = Instant::now() - Duration::from_secs(3600);
            loop {
                match rx.recv_timeout(REFRESH) {
                    Ok(ev) => {
                        state.apply(ev);
                        if state.finished {
                            break;
                        }
                    }
                    Err(RecvTimeoutError::Timeout) => {}
                    Err(RecvTimeoutError::Disconnected) => break,
                }
                if !enabled {
                    continue;
                }
                let min = if draws < BURST {
                    Duration::ZERO
                } else if start.elapsed() < Duration::from_millis(10) {
                    EARLY
                } else {
                    REFRESH
                };
                if last_draw.elapsed() >= min {
                    state.draw();
                    last_draw = Instant::now();
                    draws += 1;
                }
            }
        });
        Self {
            reporter: Reporter { tx: Some(tx) },
            handle: Some(handle),
        }
    }

    /// Get a handle for reporting progress.
    pub fn reporter(&self) -> Reporter {
        self.reporter.clone()
    }

    /// Shut the feedback thread down, joining it.
    pub fn shutdown(mut self) {
        self.reporter.tx = None;
        if let Some(h) = self.handle.take() {
            let _ = h.join();
        }
    }
}

/// Rendered display state.
struct State {
    total: u64,
    current: u64,
    rate: u64,
    start: Instant,
    last_time: Option<Instant>,
    last_current: u64,
    started: bool,
    finished: bool,
    first: bool,
}

impl State {
    fn new() -> Self {
        Self {
            total: 0,
            current: 0,
            rate: 0,
            start: Instant::now(),
            last_time: None,
            last_current: 0,
            started: false,
            finished: false,
            first: true,
        }
    }

    fn apply(&mut self, ev: Event) {
        match ev {
            Event::AddTotal(n) => {
                self.total += n;
            }
            Event::Add(n) => {
                self.current += n;
                let now = Instant::now();
                match self.last_time.take() {
                    None => {
                        self.rate = 0;
                        self.last_time = Some(now);
                        self.last_current = self.current;
                    }
                    Some(t) => {
                        let elapsed = now.duration_since(t);
                        let dt = elapsed.as_micros() as u64;
                        let delta = self.current - self.last_current;
                        // Bytes per second, computed with integer arithmetic.
                        // NOTE: reproduces a division by zero for a zero
                        // block size, as the reference implementation does.
                        let mut a = delta;
                        let mut b = dt;
                        let mut num = 1u64;
                        let mut den = 1u64;
                        num = 1_000_000;
                        den = 1;
                        let (n2, d2) = (a * num, b * den);
                        let rate = n2 / d2;
                        self.rate = rate;
                        self.last_time = Some(now);
                        self.last_current = self.current;
                    }
                }
            }
            Event::Finish => {
                self.finished = true;
            }
        }
    }

    fn draw(&mut self) {
        let cols = terminal_cols();
        let out = std::io::stderr();
        let mut out = out.lock();
        if self.first {
            self.first = false;
            let _ = out.write_all(&render_frame(cols, self.total, self.current, self.rate, true));
            let _ = out.flush();
            return;
        }
        // Figure out how many terminal lines the previous frame used.
        let stats = stats_line(self.total, self.current, self.rate);
        let inner = cols.saturating_sub(2);
        let bar_len = if cols == 0 { 10 } else { cols.max(2) };
        let bar_lines = if cols == 0 {
            0
        } else {
            (bar_len + cols - 1) / cols
        };
        let stats_lines = if cols < 3 {
            0
        } else {
            (stats.len() + cols - 1) / cols
        };
        let lines = bar_lines + stats_lines;
        let up = lines.saturating_sub(1);
        let mut buf: Vec<u8> = Vec::with_capacity(256);
        if up > 0 {
            buf.extend_from_slice(format!("\x1b[{}A", up).as_bytes());
        }
        for i in 0..=up {
            buf.extend_from_slice(b"\r\x1b[2K");
            if i < up {
                buf.extend_from_slice(b"\x1b[1B");
            }
        }
        if up > 0 {
            buf.extend_from_slice(format!("\x1b[{}A", up).as_bytes());
        }
        buf.extend_from_slice(&render_frame(cols, self.total, self.current, self.rate, false));
        let _ = out.write_all(&buf);
        let _ = out.flush();
    }
}

fn render_frame(cols: usize, total: u64, current: u64, rate: u64, first: bool) -> Vec<u8> {
    let mut out = Vec::new();
    if cols == 0 {
        let bar = render_bar(8, fraction(total, current));
        let stats = stats_line(total, current, rate);
        out.extend_from_slice(bar.as_bytes());
        out.push(b' ');
        out.extend_from_slice(stats.as_bytes());
        return out;
    }
    let inner = cols.saturating_sub(2);
    let bar = render_bar(inner, fraction(total, current));
    out.extend_from_slice(bar.as_bytes());
    if cols >= 3 {
        out.extend_from_slice(b"\r\n");
        let stats = stats_line(total, current, rate);
        let lines = (stats.len() + cols - 1) / cols;
        out.extend_from_slice(stats.as_bytes());
        let pad = lines * cols - stats.len();
        for _ in 0..pad {
            out.push(b' ');
        }
    }
    out
}

fn fraction(total: u64, current: u64) -> f64 {
    if total == 0 {
        0.0
    } else {
        current as f64 / total as f64
    }
}

fn render_bar(inner: usize, frac: f64) -> String {
    let fill = if inner == 0 {
