//! Progress bar ("feedback") implementation for xcp.
//!
//! The progress display is intentionally simple: a two line bar showing the
//! amount transferred, the percentage complete, the current transfer rate and
//! an estimate of the time remaining.
//!
//! Ownership of the display state lives with a background thread.  Copy
//! workers report their progress through a channel; the thread applies the
//! updates to its own state and renders the display at a cadence which is
//! independent of the copy loop.  This keeps the copy workers free from any
//! terminal output work, which matters when many workers are active.
//!
//! Reporting is done through a [`Reporter`] handle which may be cloned freely
//! and shared between the walk worker and the copy workers.  The walk worker
//! reports the total byte count as files are discovered (so that the bar
//! reflects the whole transfer even before it starts), while the copy workers
//! report the number of bytes actually transferred.
//!
//! The display is only drawn when standard error is a terminal; when it is
//! not, the thread still runs (and consumes progress reports) but nothing is
//! written.  This keeps the behaviour of a piped run identical to that of an
//! interactive one apart from the missing display.
//!
//! Rendering details
//! -----------------
//!
//! Two rendering modes exist, selected by the reported terminal width:
//!
//! * A width of zero (the terminal size could not be determined) selects a
//!   single line mode where the bar and the statistics share one line and are
//!   redrawn with a carriage return and an erase-to-end-of-line sequence.
//! * Otherwise the bar occupies one line and the statistics follow on the
//!   next; when the statistics are wider than the terminal they are padded to a
//!   multiple of the width so that the cursor ends on a line boundary, which
//!   makes erasing the previous frame simple.
//!
//! The bar itself consists of a filled portion of `#` characters, a leading
//! edge marker `>` and a trailing run of `-` characters, all enclosed in
//! square brackets.  When the transfer is complete the leading edge marker is
//! omitted.

use std::io::Write;
use std::sync::mpsc::{channel, RecvTimeoutError, Sender};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use crate::errors::*;

/// Interval between automatic redraws once the transfer is under way.
const REFRESH: Duration = Duration::from_millis(50);
/// Interval used while the transfer is still in its first few milliseconds.
const EARLY: Duration = Duration::from_millis(1);
/// Number of updates which are always drawn immediately.
const BURST: usize = 10;
/// Width of the bar when the terminal size is unknown.
const FALLBACK_BAR: usize = 10;
/// Number of characters used to display the rate.
const RATE_WIDTH: usize = 15;

/// Message sent to the feedback thread.
pub enum Event {
    /// Increase the total byte count by `n`.
    AddTotal(u64),
    /// Report `n` more bytes as having been transferred.
    Add(u64),
    /// The transfer has finished; force a final redraw.
    Finish,
}

/// Handle used by the workers to report progress.
#[derive(Clone)]
pub struct Reporter {
    tx: Option<Sender<Event>>,
}

impl Reporter {
    /// Report that `n` more bytes have been transferred.
    ///
    /// Returns an error when the feedback thread has gone away, which is how
    /// the copy loop learns that something went badly wrong.
    pub fn add(&self, n: u64) -> Result<(), Error> {
        if let Some(tx) = &self.tx {
            tx.send(Event::Add(n)).map_err(|_| {
                Error::new(COPY, "Error during copy operation")
            })?;
        }
        Ok(())
    }

    /// Report that `n` more bytes belong to the total.
    pub fn add_total(&self, n: u64) {
        if let Some(tx) = &self.tx {
            let _ = tx.send(Event::AddTotal(n));
        }
    }

    /// Signal completion.
    pub fn finish(&self) {
        if let Some(tx) = &self.tx {
            let _ = tx.send(Event::Finish);
        }
    }
}

/// Compute the transfer rate in bytes per second from a byte delta and the
/// elapsed time in microseconds.
///
/// Integer arithmetic is used throughout.  This mirrors the reference
/// implementation, which happily divides by zero when two updates arrive with
/// no measurable time between them.
fn calc_rate(delta: u64, micros: u64) -> u64 {
    let n = delta * 1_000_000;
    let d = micros;
    let rr = n / d;
    rr
}

/// Owns the feedback thread.
pub struct Feedback {
    reporter: Reporter,
    handle: Option<JoinHandle<()>>,
}
