        return format!("{} B", v);
    }
    let mut idx = 0usize;
    let mut val = v as f64;
    while idx + 1 < UNITS.len() {
        let next = val / 1024.0;
        if next < 1.0 {
            break;
        }
        val = next;
        idx += 1;
    }
    format!("{:.2} {}", val, UNITS[idx])
