    /// Follow symlinks in the source tree.
    pub dereference: bool,
    /// Refuse to overwrite existing files.
    pub no_clobber: bool,
    /// Backup policy for overwritten files.
    pub backup: BackupMode,
    /// Size of the chunks used for progress reporting.
    pub block_size: u64,
}

/// Find the next available backup name for `path`.
pub fn next_backup(path: &Path) -> Option<PathBuf> {
    let name = path.file_name()?.to_os_string();
    let parent = path.parent()?.to_path_buf();
    let mut highest: u64 = 0;
    let mut found = false;
    let prefix: String = format!("{}~", name.to_string_lossy());
    if let Ok(rd) = std::fs::read_dir(&parent) {
        for e in rd.flatten() {
            let n = e.file_name();
            let n = n.to_string_lossy();
            if let Some(rest) = n.strip_suffix('~') {
                if let Some(num) = rest.strip_prefix(&prefix) {
                    if let Ok(v) = num.parse::<u64>() {
                        if !found || v > highest {
                            highest = v;
                        }
                        found = true;
                    }
    }
                }
        }
    }
    if !found {
        return None;
    }
    Some(parent.join(format!("{}.~{}~", name.to_string_lossy(), highest + 1)))
}

/// Walk the given sources, sending copy operations to `tx`.
pub fn walk(
    sources: &[PathBuf],
    dest: &Path,
    opts: &CopyOpts,
    tx: &Sender<Op>,
    err_tx: &Sender<Result<(), Error>>,
    reporter: &Reporter,
) -> Result<(), Error> {
    for source in sources {
        let base = if dest.is_dir() {
            match source.file_name() {
                Some(n) => dest.join(n),
                None => dest.to_path_buf(),
            }
        } else {
            dest.to_path_buf()
        };
        debug!("Target base is {:?}", base);
        let walker = WalkDir::new(source).follow_links(opts.dereference);
        for entry in walker {
            let entry = match entry {
                Ok(e) => e,
                Err(e) => return Err(from_walk(e)),
            };
            debug!("Got tree entry {:?}", DirEntry(entry.path().to_path_buf()));
            let target = match entry.depth() {
                0 => base.clone(),
                _ => match entry.path().strip_prefix(source) {
                    Ok(rel) => base.join(rel),
                    Err(_) => base.clone(),
                },
            };
            if opts.no_clobber && target.exists() {
                let e = Error::with_path(
                    DEST_EXISTS,
                    "Destination file exists and --no-clobber is set.",
                    target.clone(),
                );
                let _ = err_tx.send(Err(e));
                return Ok(());
            }
            let ft = entry.file_type();
            if ft.is_dir() {
                debug!("Creating target directory {:?}", target);
                if let Err(e) = fsops::create_dir(&target) {
                    log::error!("Error creating target directory: {}", e);
                    return Err(Error::new(COPY, format!("Error creating target directory: {}", e)));
                }
            } else if ft.is_symlink() {
                let link = match fsops::read_link(entry.path()) {
                    Ok(l) => l,
                    Err(e) => return Err(Error::new(COPY, e.to_string())),
                };
                debug!("Send symlink operation {:?} to {:?}", link, target);
                if tx.send(Op::Link(link, target)).is_err() {
                    return Ok(());
                }
            } else if ft.is_file() {
                debug!("Send copy operation {:?} to {:?}", entry.path(), target);
                if let Some(sz) = entry.metadata().ok().map(|m| m.len()) {
                    reporter.add_total(sz);
                }
                if tx.send(Op::Copy(entry.path().to_path_buf(), target)).is_err() {
                    return Ok(());
                }
            } else {
                debug!("Special file found: {:?} to {:?}", entry.path(), target);
                if tx.send(Op::Special(entry.path().to_path_buf(), target)).is_err() {
                    return Ok(());
                }
            }
        }
    }
    debug!("Walk-worker finished: {:?}", std::thread::current().id());
    Ok(())
}

/// Debug wrapper which prints as `DirEntry("path")`.
pub struct DirEntry(pub PathBuf);

impl std::fmt::Debug for DirEntry {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "DirEntry({:?})", self.0)
    }
}

macro_rules! debug {
    ($($arg:tt)*) => { log::debug!($($arg)*) };
}

/// Copy the contents of a single regular file.
pub fn copy_file(
    from: &Path,
    to: &Path,
    opts: &CopyOpts,
    reporter: &Reporter,
) -> Result<(), Error> {
    let src = File::open(from).map_err(Error::io)?;
    let dst = OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(to)
        .map_err(Error::io)?;
    let info = fsops::fstat(&src).map_err(Error::io)?;
    // Pre-size the destination so that any holes in the source are
    // reproduced rather than written out as data.
    dst.set_len(info.size).map_err(Error::io)?;
    let result = copy_data(&src, &dst, &info, opts, reporter);
    if let Err(e) = fsops::copy_xattrs(&src, &dst) {
        return Err(Error::new(COPY, e.to_string()));
    }
    if opts.perms {
        if let Err(e) = fsops::copy_permissions(&info, &dst) {
            return Err(Error::new(COPY, e.to_string()));
        }
    }
    if opts.timestamps {
        if let Err(e) = fsops::copy_timestamps(&info, &dst) {
            return Err(Error::new(COPY, e.to_string()));
        }
    }
    if opts.ownership {
        if fsops::copy_ownership(&info, &dst).is_err() {
            log::warn!("Failed to copy file ownership: {:?}", src);
        }
    }
    if opts.fsync {
        debug!("Syncing file {:?}", dst);
        if unsafe { libc::fsync(dst.as_raw_fd()) } < 0 {
            return Err(Error::io(std::io::Error::last_os_error()));
        }
    }
    result
}

/// Copy the data of `from` into `to`.
fn copy_data(
    from: &File,
    to: &File,
    info: &fsops::SourceInfo,
    opts: &CopyOpts,
    reporter: &Reporter,
) -> Result<(), Error> {
    debug!(
        "Attempting reflink from {:?}->{:?}",
        from,
        to
    );
    if reflink(from, to) {
        return Ok(());
    }
    match opts.reflink {
        ReflinkMode::Always => {
            return Err(Error::new(
                COPY,
                format!(
                    "Failed to reflink file and 'always' was specified: {:?}->{:?}",
                    from, to
                ),
            ));
        }
        _ => {}
    }
    debug!("Failed to reflink, falling back to copy");
    let size = info.size;
    let chunk = opts.block_size.max(1024 * 1024);
    let mut pos: u64 = 0;
    let mut reported: u64 = 0;
    while pos < size {
        let want = std::cmp::min(chunk, size - pos);
        let n = copy_range(from, pos, to, pos, want)?;
        if n == 0 {
            break;
        }
        pos += n;
        while reported < pos {
            let step = std::cmp::min(opts.block_size.max(1), pos - reported);
            reporter.add(step)?;
            reported += step;
        }
    }
    while reported < size {
        let step = std::cmp::min(opts.block_size.max(1), size - reported);
        reporter.add(step)?;
        reported += step;
    }
    Ok(())
}

/// Attempt a reflink from `from` to `to` using the FICLONE ioctl.
fn reflink(from: &File, to: &File) -> bool {
    const FICLONE: libc::c_ulong = 0x40049409;
    let res = unsafe { libc::ioctl(to.as_raw_fd(), FICLONE, from.as_raw_fd()) };
    res == 0
}

/// Copy `len` bytes using copy_file_range.
fn copy_range(
    from: &File,
    from_off: u64,
    to: &File,
    to_off: u64,
    len: u64,
) -> Result<u64, Error> {
    let mut done: usize = 0;
    let len = len as usize;
    while done < len {
        let n = unsafe {
            libc::copy_file_range(
                from.as_raw_fd(),
                &mut (from_off + done as u64) as *mut u64 as *mut libc::off_t,
                to.as_raw_fd(),
                &mut (to_off + done as u64) as *mut u64 as *mut libc::off_t,
                len - done,
                0,
            )
        };
        if n < 0 {
            return Err(Error::io(std::io::Error::last_os_error()));
        }
        if n == 0 {
            break;
        }
        done += n as usize;
    }
    Ok(done as u64)
}

/// Reproduce a special file at `to`.
pub fn copy_special(from: &Path, to: &Path) -> Result<(), Error> {
    let info = fsops::lstat_path(from).map_err(Error::io)?;
    fsops::make_special(&info, to).map_err(Error::io)
}
