//! The default driver: parallelism at the file level.

use std::path::Path;
use std::sync::mpsc::{channel, Sender};
use std::thread;

use crate::drivers::{DriverOpts, CopyOpts};
use crate::errors::Error;
use crate::feedback::Reporter;
use crate::operations::{self, Op};

/// Number of copy workers to use, resolving the special `0` case.
pub fn worker_count(opts: &DriverOpts) -> usize {
    if opts.workers == 0 {
        std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1)
    } else {
        opts.workers
    }
}

/// Perform the copy, parallelising over files.
pub fn run(
    sources: &[std::path::PathBuf],
    dest: &Path,
    opts: &DriverOpts,
    reporter: &Reporter,
) -> Result<(), Error> {
    let copts: CopyOpts = opts.into();
    let workers = worker_count(opts);
    let (op_tx, op_rx) = channel::<Op>();
    let (err_tx, err_rx) = channel::<Result<(), Error>>();

    let walk_tx = op_tx.clone();
    let walk_err = err_tx.clone();
    let walk_sources: Vec<_> = sources.to_vec();
    let wdest = dest.to_path_buf();
    let wopts = copts.clone();
    let wrep = reporter.clone();
    let walk_handle = thread::spawn(move || {
        let _ = operations::walk(&walk_sources, &wdest, &wopts, &walk_tx, &walk_err, &wrep);
        drop(walk_tx);
    });

    let mut handles = Vec::new();
    for _ in 0..workers {
        let rx = op_rx.clone();
        let etx = err_tx.clone();
        let co = copts.clone();
        let rep = reporter.clone();
        handles.push(thread::spawn(move || {
            debug_start();
            loop {
                match rx.recv() {
                    Ok(op) => {
                        log::debug!("Received operation {:?}", op);
                        match op {
                            Op::Copy(from, to) => {
                                log::info!("Worker[{:?}]: Copy {:?} -> {:?}", thread::current().id(), from, to);
                                if let Err(e) = operations::copy_file(&from, &to, &co, &rep) {
                                    log::error!("Error copying: {:?} -> {:?}; aborting.", from, to);
                                    let _ = etx.send(Err(e));
                                } else {
                                    let _ = etx.send(Ok(()));
                                }
                            }
                            Op::Link(target, to) => {
                                log::info!("Worker[{:?}]: Symlink {:?} -> {:?}", thread::current().id(), target, to);
                                match libfs::common::make_symlink(&target, &to) {
                                    Ok(()) => {
                                        let _ = etx.send(Ok(()));
                                    }
                                    Err(e) => {
                                        log::error!("Error copying: {:?} -> {:?}; aborting.", target, to);
                                        let _ = etx.send(Err(Error::new(crate::errors::COPY, e.to_string())));
                                    }
                                }
                            }
                            Op::Special(from, to) => {
                                log::info!("Worker[{:?}]: Special file {:?} -> {:?}", thread::current().id(), from, to);
                                match operations::copy_special(&from, &to) {
                                    Ok(()) => {
                                        let _ = etx.send(Ok(()));
                                    }
                                    Err(e) => {
                                        log::error!("Error copying: {:?} -> {:?}; aborting.", from, to);
                                        let _ = etx.send(Err(Error::new(crate::errors::COPY, e.to_string())));
                                    }
                                }
                            }
                        }
                    }
                    Err(_) => {
                        log::debug!("Copy worker {:?} shutting down", thread::current().id());
                        break;
                    }
                }
            }
        }));
    }

    drop(op_tx);
    drop(err_tx);
    for res in err_rx {
        if let Err(e) = res {
            log::error!("Received error: {}", e);
            return Err(e);
        }
    }
    let _ = walk_handle.join();
    for h in handles {
        let _ = h.join();
    }
    Ok(())
}

fn debug_start() {
    log::debug!("Starting copy worker {:?}", thread::current().id());
}
