                    }
                }
            }
        }));
    }

    drop(op_tx);
    drop(err_tx);
    for res in err_rx {
        if let Err(e) = res {
            log::error!("Received error: {}", e);
            return Err(e);
        }
    }
    let _ = walk_handle.join();
    for h in handles {
        let _ = h.join();
    }
    Ok(())
}

