use crate::drivers::{CopyOpts, DriverOpts};
use crate::errors::Error;
use crate::feedback::Reporter;
use crate::operations::{self, Op};
use libfs::common as fsops;

/// A single range of a file to be copied.
struct Block {
    src: File,
    dst: File,
    from_path: PathBuf,
    to_path: PathBuf,
    off: u64,
    len: u64,
    step: u64,
    finalize: bool,
    info: fsops::SourceInfo,
    opts: CopyOpts,
}

/// Number of workers, resolving the `0` case.
fn worker_count(opts: &DriverOpts) -> usize {
    if opts.workers == 0 {
        std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1)
    } else {
        opts.workers
    }
}

/// Perform the copy, parallelising over block ranges.
pub fn run(
    sources: &[PathBuf],
    dest: &Path,
    opts: &DriverOpts,
    reporter: &Reporter,
) -> Result<(), Error> {
    let copts: CopyOpts = opts.into();
    let workers = worker_count(opts);
    let (op_tx, op_rx) = channel::<Op>();
    let (err_tx, err_rx) = channel::<Result<(), Error>>();
    let (blk_tx, blk_rx) = channel::<Block>();
    let (res_tx, res_rx) = channel::<bool>();

    let disp_op_rx = op_rx;
    let disp_blk_tx = blk_tx;
    let disp_res_rx = res_rx;
    let disp_err = err_tx.clone();
    let dco = copts.clone();
    let drep = reporter.clone();
    let dispatch_handle = thread::spawn(move || {
        dispatch(
            disp_op_rx,
            disp_blk_tx,
            disp_res_rx,
            disp_err,
            &dco,
            &drep,
        );
    });

    let walk_tx = op_tx.clone();
    let walk_err = err_tx.clone();
    let walk_sources: Vec<_> = sources.to_vec();
    let wdest = dest.to_path_buf();
    let wopts = copts.clone();
    let wrep = reporter.clone();
    let walk_handle = thread::spawn(move || {
        let _ = operations::walk(&walk_sources, &wdest, &wopts, &walk_tx, &walk_err, &wrep);
        drop(walk_tx);
    });

    let mut pool = Vec::new();
    for _ in 0..workers {
        let rx = blk_rx;
        let etx = err_tx.clone();
        let rep = reporter.clone();
        pool.push(thread::spawn(move || {
            let rx = rx;
            while let Ok(mut b) = rx.recv() {
                let ok = copy_block(&mut b, &rep);
                if b.finalize {
                    finalize(&b);
                }
                let _ = res_tx.send(ok);
            }
            let _ = etx.send(Ok(()));
        }));
    }

    drop(op_tx);
    drop(blk_tx);
    drop(res_tx);
    drop(err_tx);
    for res in err_rx {
        if let Err(e) = res {
            log::error!("Received error: {}", e);
            return Err(e);
        }
    }
    let _ = walk_handle.join();
    for h in pool {
        let _ = h.join();
    }
    log::info!("Pool complete");
    let _ = dispatch_handle.join();
    Ok(())
}

fn dispatch(
    op_rx: std::sync::mpsc::Receiver<Op>,
    blk_tx: Sender<Block>,
    mut res_rx: std::sync::mpsc::Receiver<bool>,
    err_tx: Sender<Result<(), Error>>,
    opts: &CopyOpts,
    reporter: &Reporter,
) {
    while let Ok(op) = op_rx.recv() {
        match op {
            Op::Copy(from, to) => {
                if let Err(e) = dispatch_one(&from, &to, opts, reporter, &blk_tx, &mut res_rx, &err_tx) {
                    let _ = err_tx.send(Err(e));
                    break;
                }
            }
            Op::Link(target, to) => {
                log::info!("Dispatch[{:?}]: Symlink {:?} -> {:?}", thread::current().id(), target, to);
                match libfs::common::make_symlink(&target, &to) {
                    Ok(()) => {}
                    Err(e) => {
                        let _ = err_tx.send(Err(Error::new(crate::errors::COPY, e.to_string())));
                        break;
                    }
                }
            }
            Op::Special(from, to) => {
                log::info!("Dispatch[{:?}]: Special file {:?} -> {:?}", thread::current().id(), from, to);
                if let Err(e) = operations::copy_special(&from, &to) {
                    let _ = err_tx.send(Err(e));
                    break;
                }
            }
        }
    }
    drop(op_rx);
    log::info!("Queuing complete");
}

#[allow(clippy::too_many_arguments)]
fn dispatch_one(
    from: &Path,
    to: &Path,
    opts: &CopyOpts,
    reporter: &Reporter,
    blk_tx: &Sender<Block>,
    res_rx: &mut std::sync::mpsc::Receiver<bool>,
    err_tx: &Sender<Result<(), Error>>,
) -> Result<(), Error> {
    log::info!(
        "Dispatch[{:?}]: Copy {:?} -> {:?}",
        thread::current().id(),
        from,
        to
    );
    let src = File::open(from).map_err(Error::io)?;
    let dst = OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(to)
        .map_err(Error::io)?;
    let info = fsops::fstat(&src).map_err(Error::io)?;
    dst.set_len(info.size).map_err(Error::io)?;
    log::debug!(
        "Attempting reflink from {:?}->{:?}",
        src,
        dst
    );
    if crate::operations::reflink_ok(&src, &dst) {
        finish_meta(&src, &dst, &info, opts);
        return Ok(());
    }
    if opts.reflink == crate::parse::ReflinkMode::Always {
        finish_meta(&src, &dst, &info, opts);
        return Err(Error::new(
            crate::errors::COPY,
            format!(
                "Failed to reflink file and 'always' was specified: {:?}->{:?}",
                src, dst
            ),
        ));
    }
    log::debug!("Failed to reflink, falling back to copy");
    let chunk = opts.block_size.max(1024 * 1024);
    let size = info.size;
    let mut off: u64 = 0;
    let mut blocks: Vec<(u64, u64)> = Vec::new();
    while off < size {
        let len = std::cmp::min(chunk, size - off);
        blocks.push((off, len));
        off += len;
    }
    let nblocks = blocks.len();
    for (i, (off, len)) in blocks.iter().enumerate() {
        let b = Block {
            src: src.try_clone().map_err(Error::io)?,
            dst: dst.try_clone().map_err(Error::io)?,
            from_path: from.to_path_buf(),
            to_path: to.to_path_buf(),
            off: *off,
            len: *len,
            step: opts.block_size.max(1),
            finalize: i + 1 == nblocks,
            info: info.clone(),
            opts: opts.clone(),
        };
        if blk_tx.send(b).is_err() {
            return Err(Error::new(crate::errors::COPY, "Error during copy operation"));
        }
    }
    let mut ok = true;
    for _ in 0..nblocks {
        match res_rx.recv() {
            Ok(v) => {
                if !v {
                    ok = false;
                }
            }
            Err(_) => {
                ok = false;
            }
        }
    }
    if !ok {
        log::error!("Dispatcher: Error copying {:?} -> {:?}.", from, to);
        return Err(Error::new(crate::errors::COPY, "Error during copy operation"));
    }
    Ok(())
}

fn copy_block(b: &mut Block, reporter: &Reporter) -> bool {
    let mut done: u64 = 0;
    let mut reported: u64 = 0;
    while done < b.len {
        let want = std::cmp::min(1024 * 1024, b.len - done);
        match crate::operations::copy_range_at(&b.src, b.off + done, &b.dst, b.off + done, want) {
            Ok(n) => {
                if n == 0 {
                    break;
                }
                done += n;
                while reported < done {
                    let step = std::cmp::min(b.step, done - reported);
                    if reporter.add(step).is_err() {
                        return false;
                    }
                    reported += step;
                }
            }
            Err(_) => return false,
        }
    }
    while reported < b.len {
        let step = std::cmp::min(b.step, b.len - reported);
        if reporter.add(step).is_err() {
            return false;
        }
        reported += step;
    }
    true
}

fn finalize(b: &Block) {
    if let Err(e) = fsops::copy_xattrs(&b.src, &b.dst) {
        log::debug!("xattr copy failed: {}", e);
        return;
    }
    if b.opts.perms {
        let _ = fsops::copy_permissions(&b.info, &b.dst);
    }
    if b.opts.timestamps {
        let _ = fsops::copy_timestamps(&b.info, &b.dst);
    }
    if b.opts.ownership {
        if fsops::copy_ownership(&b.info, &b.dst).is_err() {
            log::warn!("Failed to copy file ownership: {:?}", b.src);
        }
    }
    if b.opts.fsync {
        log::debug!("Syncing file {:?}", b.dst);
        unsafe {
            libc::fsync(b.dst.as_raw_fd());
        }
    }
}

fn finish_meta(src: &File, dst: &File, info: &fsops::SourceInfo, opts: &CopyOpts) {
    let _ = fsops::copy_xattrs(src, dst);
    if opts.perms {
        let _ = fsops::copy_permissions(info, dst);
    }
    if opts.timestamps {
        let _ = fsops::copy_timestamps(info, dst);
    }
    if opts.ownership {
        if fsops::copy_ownership(info, dst).is_err() {
            log::warn!("Failed to copy file ownership: {:?}", src);
        }
    }
    if opts.fsync {
        log::debug!("Syncing file {:?}", dst);
        unsafe {
            libc::fsync(dst.as_raw_fd());
        }
    }
}
EOF
echo ok"}

