//! Simple logging setup matching the original tool's output format.

use std::io::Write;
use std::sync::OnceLock;

/// Install the logger.  `verbosity` is the number of `-v` flags given.
pub fn init(verbosity: u8) {
    let level = match verbosity {
        0 => log::LevelFilter::Warn,
        1 => log::LevelFilter::Info,
        2 => log::LevelFilter::Debug,
        _ => log::LevelFilter::Trace,
    };
    let _ = log::set_boxed_logger(Box::new(Logger { level }));
    log::set_max_level(level);
}

struct Logger {
    level: log::LevelFilter,
}

impl log::Log for Logger {
    fn enabled(&self, meta: &log::Metadata) -> bool {
        meta.level() <= self.level
    }

    fn log(&self, record: &log::Record) {
        if !self.enabled(record.metadata()) {
            return;
        }
        let stamp = timestamp();
        let stderr = std::io::stderr();
        let mut out = stderr.lock();
        match record.level() {
            log::Level::Debug | log::Level::Trace => {
                let tid = thread_id();
                let _ = writeln!(
                    out,
                    "{} [{}] ({}) {}: {}",
                    stamp,
                    record.level(),
                    tid,
                    record.target(),
                    record.args()
                );
            }
            _ => {
                let _ = writeln!(out, "{} [{}] {}", stamp, record.level(), record.args());
            }
        }
        let _ = out.flush();
    }

    fn flush(&self) {
        let _ = std::io::stderr().flush();
    }
}

/// Current UTC time formatted as HH:MM:SS.
fn timestamp() -> String {
    unsafe {
        let mut ts: libc::timespec = std::mem::zeroed();
        if libc::clock_gettime(libc::CLOCK_REALTIME, &mut ts) != 0 {
            return "00:00:00".to_string();
        }
        let mut tm: libc::tm = std::mem::zeroed();
        let t = ts.tv_sec as libc::time_t;
        if libc::gmtime_r(&t, &mut tm).is_null() {
            return "00:00:00".to_string();
        }
        format!(
            "{:02}:{:02}:{:02}",
            tm.tm_hour, tm.tm_min, tm.tm_sec
        )
    }
}

fn thread_id() -> String {
    format!("{:?}", std::thread::current().id())
}
