use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::mpsc::{channel, RecvTimeoutError, Sender};
use std::sync::{Arc, Condvar, Mutex};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use crate::errors::*;

/// Interval between automatic redraws once the transfer is under way.
const REFRESH: Duration = Duration::from_millis(50);
/// Interval used while the transfer is still in its first few milliseconds.
const EARLY: Duration = Duration::from_millis(1);
/// Number of updates which are always drawn immediately.
const BURST: usize = 10;
/// Width of the bar when the terminal size is unknown.
const FALLBACK_BAR: usize = 10;
/// Number of characters used to display the rate.
const RATE_WIDTH: usize = 15;

'''
mid = '''/// Compute the transfer rate in bytes per second from the total transferred
/// so far and the elapsed time in microseconds.
///
/// Integer arithmetic is used throughout.
fn calc_rate(total: u64, micros: u64) -> u64 {
    let n = total * 1_000_000;
    let d = micros;
    let rate = n / d;
    rate
}

/// Estimate the number of seconds remaining from the outstanding byte count
/// and the current rate.
///
/// As with the rate this is integer arithmetic, and it happily divides by
/// zero when no progress is being made.
fn calc_eta(remaining: u64, rate: u64) -> u64 {
    let n = remaining;
    let d = rate;
    let secs = n / d;
    secs
}

