use std::io::Write;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::mpsc::{channel, RecvTimeoutError, Sender};
use std::sync::{Arc, Condvar, Mutex};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use crate::errors::*;

/// Interval between automatic redraws once the transfer is under way.
const REFRESH: Duration = Duration::from_millis(50);
/// Interval used while the transfer is still in its first few milliseconds.
const EARLY: Duration = Duration::from_millis(1);
/// Number of updates which are always drawn immediately.
const BURST: usize = 10;
/// Width of the bar when the terminal size is unknown.
const FALLBACK_BAR: usize = 10;
/// Number of characters used to display the rate.
const RATE_WIDTH: usize = 15;

/// Compute the transfer rate in bytes per second from the total transferred
/// so far and the elapsed time in microseconds.
///
/// Integer arithmetic is used throughout.
fn calc_rate(total: u64, micros: u64) -> u64 {
    let n = total * 1_000_000;
    let d = micros;
    let rate = n / d;
    rate
}

/// Estimate the number of seconds remaining from the outstanding byte count
/// and the current rate.
///
/// As with the rate this is integer arithmetic, and it happily divides by
/// zero when no progress is being made.
fn calc_eta(remaining: u64, rate: u64) -> u64 {
    let n = remaining;
    let d = rate;
    let secs = n / d;
    secs
}

/// Message sent to the feedback thread.
pub enum Event {
    /// Increase the total byte count by `n`.
    AddTotal(u64),
    /// Report `n` more bytes as having been transferred.
    Add(u64),
    /// The transfer has finished; force a final redraw.
    Finish,
    /// The transfer failed: erase the display before reporting the error.
    Cleanup,
}

/// Shared bookkeeping used to make progress reports synchronous.
#[derive(Default)]
pub struct Sync {
    /// Number of events the feedback thread has applied.
    applied: AtomicU64,
    /// Condvar signalled whenever `applied` changes.
    cond: Condvar,
    /// Mutex guarding the condvar's state.
    lock: Mutex<u64>,
}

impl Sync {
    /// Wait until the feedback thread has applied `want` events.
    fn wait_for(&self, want: u64) {
        let mut guard = self.lock.lock().expect("progress lock");
        while *guard < want {
            let res = self.cond.wait_timeout(guard, Duration::from_millis(50));
            guard = match res {
                Ok(pair) => pair.0,
                Err(err) => err.into_inner().0,
            };
        }
    }

    /// Record that `n` events have been applied.
    fn applied(&self, n: u64) {
        self.applied.store(n, Ordering::SeqCst);
        let mut guard = self.lock.lock().expect("progress lock");
        *guard = n;
        self.cond.notify_all();
    }

    /// Number of events applied so far.
    fn applied_count(&self) -> u64 {
        self.applied.load(Ordering::SeqCst)
    }
}

/// Handle used by the workers to report progress.
#[derive(Clone)]
pub struct Reporter {
    tx: Option<Sender<Event>>,
    sync: Arc<Sync>,
    sent: Arc<AtomicU64>,
}

impl Reporter {
    /// Report that `n` more bytes have been transferred.
    pub fn add(&self, n: u64) -> Result<(), Error> {
        if let Some(tx) = &self.tx {
            tx.send(Event::Add(n))
                .map_err(|_| Error::new(COPY, "Error during copy operation"))?;
            self.wait();
        }
        Ok(())
    }

    /// Report that `n` more bytes belong to the total.
    pub fn add_total(&self, n: u64) {
        if let Some(tx) = &self.tx {
            let _ = tx.send(Event::AddTotal(n));
            self.wait();
        }
    }

    /// Signal completion.
    pub fn finish(&self) {
        if let Some(tx) = &self.tx {
            let _ = tx.send(Event::Finish);
            self.wait();
        }
    }

    /// Signal that the display should be cleared before exiting.
    pub fn cleanup(&self) {
        if let Some(tx) = &self.tx {
            let _ = tx.send(Event::Cleanup);
            self.wait();
        }
    }

    /// Wait for the feedback thread to have picked up everything sent.
    fn wait(&self) {
        let want = self.sent.fetch_add(1, Ordering::SeqCst) + 1;
        if self.sync.applied_count() < want {
            self.sync.wait_for(want);
        }
    }
}

/// Owns the feedback thread.
pub struct Feedback {
    reporter: Reporter,
    handle: Option<JoinHandle<()>>,
}

impl Feedback {
    /// Start the feedback thread.  `enabled` controls whether anything is
    /// actually drawn.
    pub fn new(enabled: bool) -> Self {
        let (tx, rx) = channel::<Event>();
        let sync = Arc::new(Sync::default());
        let sync2 = Arc::clone(&sync);
        let handle = std::thread::spawn(move || {
            let sync = sync2;
            let mut state = State::new();
            let mut applied: u64 = 0;
            let start = Instant::now();
            let mut draws = 0usize;
            let mut last_draw = Instant::now() - Duration::from_secs(3600);
            loop {
                match rx.recv_timeout(REFRESH) {
                    Ok(ev) => {
                        state.apply(ev);
                        applied += 1;
                        sync.applied(applied);
                        if state.finished {
                            break;
                        }
                    }
                    Err(RecvTimeoutError::Timeout) => {}
                    Err(RecvTimeoutError::Disconnected) => break,
                }
                if !enabled {
                    continue;
                }
                let min = if draws < BURST {
                    Duration::ZERO
                } else if start.elapsed() < Duration::from_millis(10) {
                    EARLY
                } else {
                    REFRESH
                };
                if last_draw.elapsed() >= min {
                    state.draw();
                    last_draw = Instant::now();
                    draws += 1;
                }
            }
            if enabled && state.cleanup {
                state.erase();
            }
        });
        Self {
            reporter: Reporter {
                tx: Some(tx),
                sync: Arc::clone(&sync),
                sent: Arc::new(AtomicU64::new(0)),
            },
            handle: Some(handle),
        }
    }

    /// Get a handle for reporting progress.
    pub fn reporter(&self) -> Reporter {
        self.reporter.clone()
    }

    /// Shut the feedback thread down, joining it.
    pub fn shutdown(mut self) {
        self.reporter.tx = None;
        if let Some(h) = self.handle.take() {
            let _ = h.join();
        }
    }
}

/// Rendered display state.
struct State {
    cleanup: bool,
    eta: u64,
    total: u64,
    current: u64,
    rate: u64,
    start: Option<Instant>,
    finished: bool,
    first: bool,
}

impl State {
    fn new() -> Self {
        Self {
            cleanup: false,
            eta: 0,
            total: 0,
            current: 0,
            rate: 0,
            start: None,
            finished: false,
            first: true,
        }
    }

    fn apply(&mut self, ev: Event) {
        match ev {
            Event::AddTotal(n) => {
                self.total += n;
            }
            Event::Add(n) => {
                self.current += n;
                let now = Instant::now();
                match self.start {
                    None => {
                        self.start = Some(now);
                        self.rate = 0;
                        self.eta = 0;
                    }
                    Some(t) => {
                        let micros = now.duration_since(t).as_micros() as u64;
                        self.rate = calc_rate(self.current, micros);
                        self.eta = calc_eta(self.total.saturating_sub(self.current), self.rate);
                    }
                }
            }
            Event::Finish => {
                self.finished = true;
            }
            Event::Cleanup => {
                self.cleanup = true;
                self.finished = true;
            }
        }
    }

    /// Erase the currently displayed frame.
    fn erase(&mut self) {
        let cols = terminal_cols();
        let lines = self.frame_lines(cols);
        let up = lines.saturating_sub(1);
        let mut buf: Vec<u8> = Vec::new();
        if up > 0 {
            buf.extend_from_slice(format!("\x1b[{}A", up).as_bytes());
        }
        for i in 0..=up {
            buf.extend_from_slice(b"\r\x1b[2K");
            if i < up {
                buf.extend_from_slice(b"\x1b[1B");
            }
        }
        if up > 0 {
            buf.extend_from_slice(format!("\x1b[{}A", up).as_bytes());
        }
        let out = std::io::stderr();
        let mut out = out.lock();
        let _ = out.write_all(&buf);
        let _ = out.flush();
    }

    fn frame_lines(&self, cols: usize) -> usize {
        if cols == 0 {
            return 1;
        }
        let bar_len = cols.max(2);
        let bar_lines = (bar_len + cols - 1) / cols;
        let stats_lines = if cols < 3 {
            0
        } else {
            let stats = stats_line(self.total, self.current, self.rate, self.eta);
            (stats.len() + cols - 1) / cols
        };
        bar_lines + stats_lines
    }

    fn draw(&mut self) {
        let cols = terminal_cols();
        let out = std::io::stderr();
        let mut out = out.lock();
        let frame = if self.first {
            self.first = false;
            render_frame(cols, self.total, self.current, self.rate, self.eta)
        } else {
            let lines = self.frame_lines(cols);
            let up = lines.saturating_sub(1);
            let mut buf: Vec<u8> = Vec::new();
            if up > 0 {
                buf.extend_from_slice(format!("\x1b[{}A", up).as_bytes());
            }
            for i in 0..=up {
                buf.extend_from_slice(b"\r\x1b[2K");
                if i < up {
                    buf.extend_from_slice(b"\x1b[1B");
                }
            }
            if up > 0 {
                buf.extend_from_slice(format!("\x1b[{}A", up).as_bytes());
            }
            buf.extend_from_slice(&render_frame(
                cols,
                self.total,
                self.current,
                self.rate,
                self.eta,
            ));
            buf
        };
        let _ = out.write_all(&frame);
        let _ = out.flush();
    }
}

/// Render one frame of output.
fn render_frame(cols: usize, total: u64, current: u64, rate: u64, eta: u64) -> Vec<u8> {
    let mut out = Vec::new();
    if cols == 0 {
        let bar = render_bar(FALLBACK_BAR - 2, fraction(total, current));
        let stats = stats_line(total, current, rate, eta);
        out.extend_from_slice(bar.as_bytes());
        out.push(b' ');
        out.extend_from_slice(stats.as_bytes());
        return out;
    }
    let inner = cols.saturating_sub(2);
    let bar = render_bar(inner, fraction(total, current));
    out.extend_from_slice(bar.as_bytes());
    if cols >= 3 {
        out.extend_from_slice(b"\n");
        let stats = stats_line(total, current, rate, eta);
        out.extend_from_slice(stats.as_bytes());
        let lines = (stats.len() + cols - 1) / cols;
        let pad = lines * cols - stats.len();
        for _ in 0..pad {
            out.push(b' ');
        }
    }
    out
}

fn fraction(total: u64, current: u64) -> f64 {
    if total == 0 {
        0.0
    } else {
        current as f64 / total as f64
    }
}

fn render_bar(inner: usize, frac: f64) -> String {
    let fill = if inner == 0 {
        0
    } else {
        (frac * inner as f64) as usize
    };
    if fill >= inner {
        let mut s = String::with_capacity(inner + 2);
        s.push('[');
        for _ in 0..inner {
            s.push('#');
        }
        s.push(']');
        s
    } else {
        let mut s = String::with_capacity(inner + 2);
        s.push('[');
        for _ in 0..fill {
            s.push('#');
        }
        s.push('>');
        for _ in 0..(inner - fill - 1) {
            s.push('-');
        }
        s.push(']');
        s
    }
}

fn stats_line(total: u64, current: u64, rate: u64, eta: u64) -> String {
    let cur = format_size(current);
    let tot = format_size(total);
    let pct = if total == 0 {
        0
    } else {
        (current as f64 / total as f64 * 100.0).round() as u64
    };
    let rate_text = format!("{}/s", format_size(rate));
    format!(
        "{:>11} / {:<12}| {:>3}% |{:^15}| {} remaining",
        cur,
        tot,
        pct,
        rate_text,
        format_duration(eta)
    )
}

/// Format a byte count the way the progress bar does.
pub fn format_size(v: u64) -> String {
    const UNITS: [&str; 9] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB"];
    if v < 1024 {
        return format!("{} B", v);
    }
    let mut idx = 0usize;
    let mut val = v as f64;
    while idx + 1 < UNITS.len() {
        let next = val / 1024.0;
        if next < 1.0 {
            break;
        }
        val = next;
        idx += 1;
    }
    format!("{:.2} {}", val, UNITS[idx])
}

fn format_duration(secs: u64) -> String {
    let h = secs / 3600;
    let m = (secs % 3600) / 60;
    let s = secs % 60;
    format!("{:02}:{:02}:{:02}", h, m, s)
}

/// Query the terminal width of standard error.
pub fn terminal_cols() -> usize {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(2, libc::TIOCGWINSZ, &mut ws as *mut libc::winsize) != 0 {
            return 0;
        }
        if ws.ws_col <= 0 {
            return 0;
        }
        ws.ws_col as usize
    }
}

/// Is standard error a terminal?
pub fn is_terminal() -> bool {
    unsafe { libc::isatty(2) == 1 }
}
