//! xcp — an extended copy utility.

use std::path::{Path, PathBuf};

use libxcp::cli::Args;
use libxcp::errors::*;
use libxcp::parse::{BackupMode, Driver};

mod logging;

fn main() -> Result<(), Error> {
    let args = libxcp::cli::parse();
    logging::init(args.verbose);

    if args.force && args.no_clobber {
        return Err(Error::new(
            INVALID_ARGS,
            "--force and --noclobber cannot be set at the same time.",
        ));
    }

    let mut sources: Vec<PathBuf> = args.paths.clone();
    let dest: PathBuf = match &args.target_directory {
        Some(td) => td.clone(),
        None => {
            if sources.is_empty() {
                return Err(Error::new(INVALID_ARGS, "Insufficient arguments"));
            }
            sources.pop().expect("checked above")
        }
    };

    if args.glob {
        sources = expand_globs(&sources)?;
    }

    if sources.is_empty() {
        return Err(Error::new(INVALID_SOURCE, "No source files found."));
    }

    if sources.len() > 1 && !dest.is_dir() {
        return Err(Error::new(
            INVALID_DEST,
            "Multiple sources and destination is not a directory.",
        ));
    }

    if sources.len() == 1 {
        if let Some(m) = std::fs::metadata(&sources[0]).ok() {
            if m.is_dir() {
                if let Some(d) = std::fs::metadata(&dest).ok() {
                    if !d.is_dir() {
                        return Err(Error::new(
                            INVALID_DEST,
                            "Cannot copy a directory to a file.",
                        ));
                    }
                }
            }
        }
    }

    for s in &sources {
        log::info!("Copying source {:?} to {:?}", s, dest);
    }

    for s in &sources {
        let meta = match std::fs::metadata(s) {
            Ok(m) => m,
            Err(_) => {
                return Err(Error::new(INVALID_SOURCE, "Source does not exist."));
            }
        };
        if meta.is_dir() && !args.recursive {
            return Err(Error::new(
                INVALID_SOURCE,
                "Source is directory and --recursive not specified.",
            ));
        }
        if same_path(s, &dest) {
            return Err(Error::new(
                INVALID_SOURCE,
                "Cannot copy a directory into itself",
            ));
        }
    }

    if args.reflink == libxcp::parse::ReflinkMode::Never {
        log::warn!("--reflink=never is selected, however the Linux kernel may override this.");
    }

    let opts = libxcp::drivers::DriverOpts {
        workers: args.workers,
        perms: !args.no_perms,
        timestamps: !args.no_timestamps,
        ownership: args.ownership,
        fsync: args.fsync,
        reflink: args.reflink,
        dereference: args.dereference,
        no_clobber: args.no_clobber,
        backup: args.backup,
        block_size: args.block_size,
    };

    let report = !args.no_progress;
    let draw = report && libxcp::feedback::is_terminal();
    let fb = libxcp::feedback::Feedback::new(report, draw);
    let reporter = fb.reporter();

    let gitignores = if args.gitignore {
        Some(sources.clone())
    } else {
        None
    };

    let res = match args.driver {
        Driver::ParFile => libxcp::drivers::run(&sources, &dest, &opts, &gitignores, &reporter),
        Driver::ParBlock => {
            libxcp::drivers::run_block(&sources, &dest, &opts, &gitignores, &reporter)
        }
    };

    match res {
        Ok(()) => {
            log::info!("Copy complete");
            reporter.finish();
            fb.shutdown();
            Ok(())
        }
        Err(e) => {
            reporter.cleanup();
            fb.shutdown();
            Err(e)
        }
    }
}

/// Expand filename patterns into the list of files they match.
fn expand_globs(patterns: &[PathBuf]) -> Result<Vec<PathBuf>, Error> {
    let mut out = Vec::new();
    for p in patterns {
        let pat = p.to_string_lossy();
        match glob::glob(&pat) {
            Ok(paths) => {
                for entry in paths {
                    if let Ok(path) = entry {
                        out.push(path);
                    }
                }
            }
            Err(e) => return Err(Error::new("", e.to_string())),
        }
    }
    Ok(out)
}

/// Compare two paths the way Rust's `Path` equality does (component wise).
fn same_path(a: &Path, b: &Path) -> bool {
    a == b
}
